/// Ends with 's' and not uncountable. The reference implementation
/// additionally treats "news" as non-plural here (unlike pluralize,
/// which happily produces "newss").
pub fn is_plural(word: &str) -> bool {
    if word == "news" || UNCOUNTABLES.contains(&word) {
        return false;
    }
    word.ends_with('s')
}
